@Test
public void reflexiveAndSymmetric() throws Exception {
    for (final T o1 : getObjectsWithSameValue()) {
        for (final T o2 : getObjectsWithSameValue()) {
            assertThat(o1.equals(o2), is(true));
            assertThat(o2.equals(o1), is(true));
