@Test
void threeHandlers_shouldProperlyTakeResponsibilityInOrder() {
    val aToUpperCase = new ChainOfResponsibility.Handler<String, String>() {

        @Override
        public boolean isHandling(String request) {
            return request.startsWith("a");
        }

        @Override
        public String handle(String request) {
            return request.toUpperCase();
        }
    };
    val bToUpperCase = new ChainOfResponsibility.Handler<String, String>() {

        @Override
        public boolean isHandling(String request) {
            return request.startsWith("b");
        }

        @Override
        public String handle(String request) {
            return request.toUpperCase();
        }
    };
    val finallyNoop = new ChainOfResponsibility.Handler<String, String>() {

        @Override
        public boolean isHandling(String request) {
            return true;
        }

        @Override
        public String handle(String request) {
            return request;
        }
    };
    val chainOfResponsibility = ChainOfResponsibility.of(Arrays.asList(aToUpperCase, bToUpperCase, finallyNoop));
    // handled by first handler
    assertEquals("ASTRING", chainOfResponsibility.handle("aString").orElse(null));
    // handled by second handler
    assertEquals("BSTRING", chainOfResponsibility.handle("bString").orElse(null));
    // handled by third handler
    assertEquals("cString", chainOfResponsibility.handle("cString").orElse(null));
}

@Test
void whenExtended_shouldWorkAsWell() {
    val aToUpperCase = new StringHandler() {

        @Override
        public boolean isHandling(String request) {
            return request.startsWith("a");
        }

        @Override
        public String handle(String request) {
            return request.toUpperCase();
        }
    };
    val handlers = Arrays.asList(aToUpperCase);
    val chainOfResponsibility = ChainOfResponsibility.of(handlers);
    // handled by first handler
    assertEquals("ASTRING", chainOfResponsibility.handle("aString").orElse(null));
    // not handled
    assertFalse(chainOfResponsibility.handle("xxx").isPresent());
}

